const moneyLabel=n=>'£'+Math.abs(n).toLocaleString('en-GB'), signedMoney=n=>(n<0?'−':n>0?'+':'')+moneyLabel(n);
const outgoingChoices={};
let marketDisplayMode='list',marketSelectedIdentity=null;
function marketOverall(p){return typeof SquadOverview!=='undefined'?SquadOverview.overall(p):p[S.primaryKey(p)];}
function marketNumber(n){const band=n>=80?'elite':n>=65?'strong':n>=50?'steady':'developing';return '<b class="market-rating" data-ability-band="'+band+'">'+n+'</b>';}
function marketListMarkup(candidates){
 return '<section class="market-candidate-list" aria-label="영입 후보 비교 목록"><div class="market-list-columns" aria-hidden="true"><span>선수 · 포지션</span><span>종합</span><span>성장</span><span>나이</span></div>'+candidates.map(p=>{
  const current=Object.values(season.squad).find(owned=>owned.identity===p.identity)||p;
  return '<button type="button" class="market-list-row" data-market-select="'+playerUiText(p.identity)+'" aria-pressed="'+(p.identity===marketSelectedIdentity)+'" aria-label="'+playerUiText(p.name+' · 종합 '+marketOverall(current)+' · 성장 한계 '+current.potential+' · 비교 보고서 보기')+'">'+Portraits.html(current)+'<span><strong>'+playerUiText(p.name)+'</strong><small>'+playerUiText(p.pos+' · '+(p.sellerClub?.short||p.sellerClub?.name||'영입 후보'))+'</small></span>'+marketNumber(marketOverall(current))+marketNumber(current.potential)+'<span>'+(p.age+season.year-1)+'</span></button>';
 }).join('')+(!candidates.length?'<p class="market-list-empty">조건에 맞는 선수가 없습니다.</p>':'')+'</section>';
}
function marketQuickCompareMarkup(candidate,outgoing){
 const rows=[['종합',marketOverall(outgoing),marketOverall(candidate)],['속도',outgoing.speed,candidate.speed],['지구력',outgoing.endurance,candidate.endurance],['성장 한계',outgoing.potential,candidate.potential]];
 return '<section class="market-quick-comparison" aria-label="현재 선수와 후보 능력 비교"><h3>'+playerUiText(outgoing.name)+'과 비교</h3><div class="market-compare-labels"><span>능력</span><span>현재 선수</span><span>후보</span></div>'+rows.map(([label,before,after])=>'<div><span>'+label+'</span>'+marketNumber(before)+marketNumber(after)+'</div>').join('')+'</section>';
}
function bindMarketWorkspace(){
 const host=$('market-overview');host.querySelectorAll('[data-market-mode]').forEach(b=>b.onclick=()=>{marketDisplayMode=b.dataset.marketMode;renderMarket();host.querySelector('[data-market-mode="'+marketDisplayMode+'"]')?.focus({preventScroll:true});});
 host.querySelectorAll('[data-market-select]').forEach(b=>b.onclick=()=>{marketSelectedIdentity=b.dataset.marketSelect;renderMarket();host.querySelector('[data-market-select="'+marketSelectedIdentity+'"]')?.focus({preventScroll:true});});
}
function recruitmentTalkBlock(slot){const talks=(state?.decisions||[]).filter(d=>d.type==='talk');return talks.some(d=>d.lineup.includes(slot))||!!season.suspensions&&talks.length>0;}
function recruitmentTalkReason(){return season.suspensions?'출전 정지 규칙이 적용된 구단은 팀 대화 전에 영입을 마쳐 주세요. 다음 리그 경기 준비 때 다시 영입할 수 있습니다.':'팀 대화를 마친 선수는 다음 경기 전에 영입으로 교체할 수 있습니다. 이번 주에는 대화에 참여하지 않은 벤치를 선택하세요.';}
function clubWeeklyWages(s=season){return E.wages(s)+(typeof Staff==='undefined'?0:Staff.wages(s));}
function matchCashflow(entry){
 if(!entry)return null;
 if(entry.type!=='match')return {...entry,staffPayroll:0};
 const staffAmount=season.finance.ledger.filter(item=>item.type==='staff-wages'&&item.year===entry.year&&item.round===entry.round).reduce((sum,item)=>sum+item.amount,0);
 return {...entry,amount:entry.amount+staffAmount,playerPayroll:entry.payroll,staffPayroll:Math.abs(staffAmount),payroll:entry.payroll-staffAmount};
}
function playerUiText(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function playerCharacterMarkup(person){const profile=F.personality?.(person);return profile?'<div class="player-character"><span class="character-nickname">'+playerUiText(profile.nickname)+'</span><p><span>스카우트 한마디</span>'+playerUiText(profile.tagline)+'</p></div>':'';}
function candidateSetPiecesMarkup(p){if(p.pos==='GK')return '';return '<div class="candidate-set-pieces" aria-label="세트피스 능력 지표">'+Object.entries(F.setPieceRoleNames).map(([role,label])=>'<div><span>'+({corner:'코너',freeKick:'프리킥',target:'공중볼'}[role])+'</span><b>'+F.setPieceScore(p,role)+'</b></div>').join('')+'</div>';}
function ownedContractMarkup(person){const status=person.injury?'부상 · '+person.injury.remaining+'경기 휴식':'현재 체력 '+Math.round(state?.players[person.id]?.energy??person.energy);return '<div class="contract-note">우리 선수단에 등록됐습니다.<br>계약 후 출전 경험 '+person.xp.toLocaleString('ko-KR')+'분<br>'+status+'</div>';}
function recruitComparisonMarkup(incoming,outgoing){
 const labels={keeping:'선방',defense:'수비',passing:'패스',attack:'결정력'},roles={GK:'골키퍼',DEF:'수비수',MID:'미드필더',FW:'공격수'},incomingKey=S.primaryKey(incoming),outgoingKey=S.primaryKey(outgoing);
 const remaining=person=>Math.max(0,person.potential-person[S.primaryKey(person)]);
 const personMarkup=(person,side,title)=>{
  const key=S.primaryKey(person),growth=remaining(person),character=typeof PlayerCharacter!=='undefined'?PlayerCharacter.info(person):F.personality?.(person);
  return '<article class="comparison-person" data-comparison-side="'+side+'" data-comparison-identity="'+playerUiText(person.identity||person.id)+'"><span class="comparison-person-label">'+title+'</span><div class="comparison-person-heading">'+Portraits.html(person)+'<div class="comparison-name"><small>'+playerUiText(person.pos+' · '+(roles[person.pos]||person.pos))+'</small><strong>'+playerUiText(person.name)+'</strong>'+(character?.nickname?'<span>'+playerUiText(character.nickname)+'</span>':'')+'</div></div><div class="comparison-growth"><span>'+labels[key]+' <b>'+person[key]+'</b> / 성장 한계 <b>'+person.potential+'</b></span><strong>'+(growth?'성장 여유 '+growth:'성장 한계 도달')+'</strong></div></article>';
 };
 const selectedRole=typeof transferFilters==='undefined'?'all':transferFilters.role,role=typeof PlayerScouting==='undefined'?null:PlayerScouting.roles[selectedRole],beforeRole=role?PlayerScouting.roleScore(outgoing,selectedRole):null,afterRole=role?PlayerScouting.roleScore(incoming,selectedRole):null;
 const values=[['primary','즉시 전력 · '+labels[incomingKey],outgoing[outgoingKey],incoming[incomingKey]],['speed','속도',outgoing.speed,incoming.speed],['endurance','지구력',outgoing.endurance,incoming.endurance],['growth','성장 여유',remaining(outgoing),remaining(incoming)],...(beforeRole!==null&&afterRole!==null?[['role',role.label+' · 코치 평가',beforeRole,afterRole]]:[])];
 return '<section class="candidate-comparison" aria-label="선택한 방출 선수와 실제 능력 비교"><div class="comparison-heading"><span>선택한 선수와 실제 능력 비교</span><strong>현재 전력과 앞으로의 성장 여유</strong></div><div class="comparison-people">'+personMarkup(outgoing,'outgoing','보낼 선수')+personMarkup(incoming,'incoming','영입 후보')+'</div><div class="comparison-grid">'+values.map(([stat,label,before,after])=>{const delta=after-before,direction=delta>0?'up':delta<0?'down':'same',change=delta>0?'+'+delta:delta<0?'−'+Math.abs(delta):'0',difference=delta===0?'같음':stat==='growth'?(delta>0?'더 큼':'더 적음'):(delta>0?'높음':'낮음');return '<div class="comparison-stat" data-comparison-stat="'+stat+'"><span>'+label+'</span><b class="comparison-delta '+direction+'">'+change+'<small>'+difference+'</small></b><small class="comparison-values">'+before+' → '+after+'</small></div>';}).join('')+'</div></section>';
}
function renderFinance(){
 if(typeof view!=='undefined'&&view!=='club'&&view!=='market')return;
 const f=season.finance,payroll=clubWeeklyWages(),last=matchCashflow(f.ledger.filter(e=>['match','cup','europe'].includes(e.type)).at(-1)),rates=E.rates(season),goalCopy=season.league.rules==='legacy'?'£30,000~£100,000':season.league.rules==='five-tier'?(season.league.division===1?'1위 £180,000 / 2~3위 £90,000 / 4~6위 £50,000':`1위 £${E.goalReward(season,1).toLocaleString('en-GB')} / 2위 £${E.goalReward(season,2).toLocaleString('en-GB')}`):season.league.division===2?'1위 £100,000 / 2위 £60,000':'1위 £180,000 / 2~3위 £90,000 / 4~6위 £50,000';
 if(typeof view==='undefined'||view==='club'){
 $('finance-summary').innerHTML=`<div class="budget-band"><div><span>구단 자금</span><strong class="${f.balance<0?'loss':''}">${f.balance<0?'−':''}${moneyLabel(f.balance)}</strong></div><div><span>주간 전체 급여</span><strong>${moneyLabel(payroll)}</strong></div><div><span>최근 경기 순수익</span><strong class="${last?.amount<0?'loss':''}">${last?signedMoney(last.amount):'첫 경기 대기'}</strong></div><button id="open-market" class="secondary">영입 시장 보기 →</button></div>`;
 $('open-market').onclick=()=>setView('market');
 }
 if(typeof view!=='undefined'&&view!=='market')return;
 $('finance-detail').innerHTML=`<div class="finance-detail"><div><div class="panel-heading"><h2>구단 장부</h2><span>최근 6건</span></div>${f.ledger.length?f.ledger.slice(-6).reverse().map(e=>`<div class="ledger-row"><div><b>${e.year}시즌 ${e.round}R · ${ledgerTitle(e)}</b><small>${ledgerDetail(e)}</small></div><strong class="${e.amount<0?'loss':''}">${signedMoney(e.amount)}</strong></div>`).join(''):'<p class="finance-note">아직 지출과 경기 수입이 없습니다. 첫 영입 또는 경기 정산 후 기록됩니다.</p>'}</div><div class="finance-rules"><div class="eyebrow">구단 운영</div><h2>${leagueTargetLabel()}를 향해.</h2><p>시즌 목표 달성 보상 · ${goalCopy}.</p><p>${season.league.division}부 리그 경기마다 홈 ${moneyLabel(rates.gateHome)} / 원정 ${moneyLabel(rates.gateAway)}, 후원 ${moneyLabel(rates.sponsor)}에서 선수와 코치 급여를 지급합니다. 승리 보너스 ${moneyLabel(rates.winBonus)} · 무승부 ${moneyLabel(rates.drawBonus)}.</p><small>£는 게임 속 구단 자금입니다. 자금이 부족해도 경기는 계속할 수 있으며 영입은 잔액 안에서만 가능합니다.</small></div></div>`;
}
function candidateScoutingMarkup(candidate,person){
 const report=person.scouting||(typeof PlayerScouting!=='undefined'?PlayerScouting.read(candidate):null);if(!report)return '';const foot=person.feet||PlayerTraits.feet(candidate),role=person.selectedRole||report.roles[0];
 return '<div class="candidate-scout-summary"><strong>'+playerUiText(report.style)+'</strong><span>'+playerUiText(foot.label)+' · '+playerUiText(PlayerTraits.preferredPositions(candidate).join(' / '))+'</span>'+(role?'<span>'+playerUiText(role.label)+' <b>'+role.score+'</b> <small>코치 평가</small></span>':'')+'</div>';
}
function renderMarket(){
 if(typeof view!=='undefined'&&view!=='market')return;
 if(typeof renderFinancePlan==='function')renderFinancePlan();
 const candidates=typeof transferCandidates==='function'?transferCandidates():F.market;
 if(!candidates.some(p=>p.identity===marketSelectedIdentity))marketSelectedIdentity=candidates[0]?.identity||null;
 const openDeals=new Set(Array.from($('market-overview').querySelectorAll('.candidate-deal-details[open]')).map(node=>node.dataset.dealIdentity));
 const f=season.finance,ready=!!state&&state.phase==='prep'&&state.minute===0&&season.competition==='league'&&season.round<S.roundCount(season),done=f.transferWeek===season.year+'-'+season.round,talkedSlots=new Set((state?.decisions||[]).filter(decision=>decision.type==='talk').flatMap(decision=>decision.lineup));
 $('market-overview').dataset.marketMode=marketDisplayMode;
 $('market-overview').innerHTML=`<nav class="market-view-toolbar" aria-label="후보 표시 방법"><button type="button" data-market-mode="list" aria-pressed="${marketDisplayMode==='list'}">목록 · 비교</button><button type="button" data-market-mode="cards" aria-pressed="${marketDisplayMode==='cards'}">카드 보기</button></nav>${marketListMarkup(candidates)}<div class="market-title"><div><div class="eyebrow">이적시장 / 시즌 ${String(season.year).padStart(2,'0')}</div><h1>지금의 한 명, 다음 시즌의 한 명.</h1><p>즉시 전력과 유망주 사이에서 결정하세요.<br>같은 포지션 선수 한 명을 보내고 차액과 수수료 £5,000을 지불합니다.</p></div><div class="market-balance"><span>현재 구단 자금</span><strong class="${f.balance<0?'loss':''}">${f.balance<0?'−':''}${moneyLabel(f.balance)}</strong><small>선수단 18명 · 구단 전체 주급 ${moneyLabel(clubWeeklyWages())}</small></div></div><div class="market-status">${season.competition==='cup'?'컵 경기 준비 · 다음 리그 준비 때 영입이 열립니다.':season.competition==='europe'?'챔피언스리그 준비 · 다음 리그 준비 때 영입이 열립니다.':done?'이번 주 영입 완료 · 경기 결과 확정 후 다음 영입이 열립니다.':ready?(talkedSlots.size?season.suspensions?'팀 대화 완료 · 다음 리그 경기 준비 때 영입 가능':'이번 주 벤치 선수 영입 가능 · 팀 대화를 마친 선발은 다음 경기 전 영입 교체 가능':'이번 주 영입 가능 · 한 주에 1명 · 영입 선수 체력 100'):season.round===S.roundCount(season)?'시즌 종료 · 다음 시즌 시작 후 영입할 수 있습니다.':'경기 진행 중 · 다음 경기 준비 때 영입할 수 있습니다.'}</div><div class="market-grid">${candidates.map(person=>{
  const owned=Object.values(season.squad).find(p=>p.identity===person.identity),owns=!!owned,candidate=owned||person,used=f.marketUsed.includes(person.identity),same=Object.values(season.squad).filter(p=>p.pos===person.pos);
  let slot=outgoingChoices[person.identity];if(!same.some(p=>p.id===slot)){slot=[...same].sort((a,b)=>Number(state?.lineup.includes(a.id))-Number(state?.lineup.includes(b.id))||a[S.primaryKey(a)]-b[S.primaryKey(b)])[0].id;outgoingChoices[person.identity]=slot;}
  const quote=E.quote(season,person.identity,slot),key=S.primaryKey(person),talkBlocked=recruitmentTalkBlock(slot),blocked=!ready||done||used||owns||talkBlocked||quote.balanceAfter<0;
  return `<article class="market-card" data-market-candidate="${playerUiText(person.identity)}" ${marketDisplayMode==='list'&&person.identity!==marketSelectedIdentity?'hidden':''}><div class="market-card-content"><div class="candidate-top"><span class="position">${person.pos}</span><span class="prospect">${owns?'우리 선수':person.kind}</span></div>${person.sellerClub?`<p class="market-origin">스카우트 발견 · ${playerUiText(person.sellerClub.name)}</p>`:''}<div class="candidate-identity">${Portraits.html(candidate,{size:'large'})}<h2>${person.name}</h2></div><button class="profile-inline-button" data-player-detail="${playerUiText(candidate.identity)}" aria-label="${playerUiText(candidate.name)} 선수 상세 보기">선수 상세 카드 ↗</button>${typeof transferShortlistMarkup==='function'?transferShortlistMarkup(person.identity):''}${candidateScoutingMarkup(candidate,person)}<p class="candidate-age">${person.age+season.year-1}세 · 주급 ${moneyLabel(person.wage)}</p><div class="candidate-stats"><div><span>주요 능력</span><b>${candidate[key]}</b></div><div><span>성장 한계</span><b>${candidate.potential}</b></div><div><span>속도</span><b>${candidate.speed}</b></div><div><span>지구력</span><b>${candidate.endurance}</b></div></div>${marketQuickCompareMarkup(candidate,season.squad[slot])}${candidateSetPiecesMarkup(candidate)}<div class="candidate-fee">영입가 <b>${moneyLabel(person.fee)}</b></div>${owns?ownedContractMarkup(owned):''}<details class="candidate-deal-details" data-deal-identity="${person.identity}" ${owns?'hidden':''} ${openDeals.has(person.identity)?'open':''}><summary>선수 교환 · 역할 · 비용 비교</summary><div><label for="out-${person.identity}">보낼 ${person.pos} 선수</label><select id="out-${person.identity}" data-outgoing="${person.identity}" ${!ready||done||used?'disabled':''}>${same.map(p=>`<option value="${p.id}" ${p.id===slot?'selected':''}>${p.name} · 주요 ${p[key]} · ${moneyLabel(E.resale(p))}${talkedSlots.has(p.id)?' · 팀 대화 완료':''}</option>`).join('')}</select>${owns?'':recruitComparisonMarkup(person,season.squad[slot])}<div class="deal-lines"><span>보낼 선수 평가액 <b>−${moneyLabel(quote.credit)}</b></span><span>수수료 <b>${moneyLabel(quote.commission)}</b></span><span>실제 영입 지출 <b>${signedMoney(quote.cost)}</b></span><span>주급 변화 <b>${signedMoney(quote.wageChange)}</b></span><span>영입 후 자금 <b class="${quote.balanceAfter<0?'loss':''}">${quote.balanceAfter<0?'−':''}${moneyLabel(quote.balanceAfter)}</b></span></div><button type="button" class="secondary finance-plan-compare" data-finance-compare="${person.identity}">영입 후 자금 계획 비교</button></div></details></div><button class="${blocked?'secondary':'primary'}" data-recruit="${person.identity}" ${blocked?'disabled':''}>${owns?'우리 구단에서 뛰는 중':used?'이번 시즌 계약 완료':done?'다음 주에 영입 가능':!ready?(season.competition==='europe'?'다음 리그 준비 때 영입 가능':'경기 준비 때 영입 가능'):talkBlocked?'팀 대화 완료 · 다음 경기 전 가능':quote.balanceAfter<0?'구단 자금 부족':person.name+' 영입 검토'}</button>${ready&&!done&&!used&&!owns&&talkBlocked?'<p class="finance-note market-talk-reason" role="status">'+recruitmentTalkReason()+'</p>':''}</article>`;
 }).join('')}</div><p class="finance-note">영입하면 선택한 선수가 구단을 떠납니다. 선발로 등록된 자리라면 영입 선수가 그 자리에 들어갑니다. 새 선수의 출전 경험은 0부터 시작합니다.</p>`;
 bindMarketWorkspace();
 $('market-overview').querySelectorAll('[data-outgoing]').forEach(select=>select.onchange=()=>{const identity=select.dataset.outgoing;outgoingChoices[identity]=select.value;renderMarket();const control=$('out-'+identity)||$('transfer-position');control?.focus?.({preventScroll:true});});
 $('market-overview').querySelectorAll('[data-finance-compare]').forEach(button=>button.onclick=()=>openFinancePlan(button.dataset.financeCompare,outgoingChoices[button.dataset.financeCompare]));
 if(typeof bindTransferShortlist==='function')bindTransferShortlist($('market-overview'));
 $('market-overview').querySelectorAll('[data-recruit]').forEach(button=>button.onclick=()=>{if(button.disabled)return;const identity=button.dataset.recruit;openRecruitmentReview(identity,outgoingChoices[identity]);});
}

function ledgerTitle(e){return ({transfer:"선수 맞교환",goal:"시즌 목표 보상",scout:"유소년 탐색",board:"이사회 과제 보상",'owner-investment':"구단주 투자",cup:"컵대회 정산",europe:"챔피언스리그 정산",'staff-hire':'코치 계약','staff-renew':'코치 재계약','staff-release':'코치 계약 종료','staff-wages':'코치 주급'}[e.type]||"경기 정산");}
function ledgerDetail(e){
 if(e.type==='owner-investment')return '면담 승인 · 시즌 한 번 · '+moneyLabel(e.amount);
 if(e.type==='europe')return Europe.stageNames[e.stage]+' · 경기 수입 '+moneyLabel(e.gate)+' / 경기 상금 '+moneyLabel(e.matchBonus)+' / 진출·우승 상금 '+moneyLabel(e.advanceBonus);
 if(e.type==='staff-wages')return '코치 '+e.contracts.length+'명 · 리그 주급 '+moneyLabel(-e.amount);
 if(['staff-hire','staff-renew','staff-release'].includes(e.type)){const person=typeof Staff==='undefined'?null:Staff.candidates(season).find(candidate=>candidate.id===e.candidate);return playerUiText(person?person.label+' · '+person.name:'코치')+' · '+(e.type==='staff-renew'?'리그 7경기 연장 / ':e.type==='staff-release'?'계약 종료 지급 / ':'계약 비용 / ')+moneyLabel(-e.amount);}
 if(e.type==="cup")return P.stageNames[e.stage]+" · 경기 수입 "+moneyLabel(e.gate)+" / 승리 상금 "+moneyLabel(e.advanceBonus);if(e.type==="transfer")return F.identityProfile(e.incoming).name+" 영입 · "+F.identityProfile(e.outgoing).name+" 이적";if(e.type==="goal")return e.achieved?"시즌 목표 달성":"시즌 목표 미달성";if(e.type==="scout")return (e.cycle===1?"전반기":"후반기")+" "+e.pos+" · 유망주 3명 발견";if(e.type==="board")return missionInfo[e.task].title+" 달성";return "경기 수입 "+moneyLabel(e.income)+" / 선수 급여 "+moneyLabel(e.payroll);
}
